import time
from retrying import retry


def test_succeeds_first_time():
    @retry(times=3, sleep=lambda s: None)
    def ok():
        return 42

    assert ok() == 42


def test_succeeds_on_second_attempt():
    calls = []

    @retry(times=3, sleep=lambda s: None)
    def flaky():
        calls.append(1)
        if len(calls) == 1:
            raise ValueError("first fail")
        return 42

    assert flaky() == 42
    assert len(calls) == 2


def test_times_validation():
    with pytest.raises(ValueError, match="times must be at least 1"):
        @retry(times=0)
        def foo():
            pass


def test_only_specified_exceptions_retry():
    calls = []

    @retry(times=3, exceptions=(ValueError,), sleep=lambda s: None)
    def flaky_value_error():
        calls.append(1)
        raise ValueError("error")

    with pytest.raises(ValueError):
        flaky_value_error()
    assert len(calls) == 3

    calls = []

    @retry(times=3, exceptions=(ValueError,), sleep=lambda s: None)
    def flaky_type_error():
        calls.append(1)
        raise TypeError("error")

    with pytest.raises(TypeError):
        flaky_type_error()
    assert len(calls) == 1


def test_reraises_last_exception():
    calls = []

    @retry(times=3, exceptions=(ValueError,), sleep=lambda s: None)
    def flaky():
        calls.append(1)
        raise ValueError("last error")

    with pytest.raises(ValueError, match="last error"):
        flaky()
    assert len(calls) == 3


def test_delays_list():
    waits = []

    def sleep_fn(s):
        waits.append(s)

    @retry(times=3, delays=[0.1, 0.5], sleep=sleep_fn, exceptions=(ValueError,))
    def flaky():
        raise ValueError("error")

    with pytest.raises(ValueError):
        flaky()

    assert waits == [0.1, 0.5]


def test_delays_short_list():
    waits = []

    def sleep_fn(s):
        waits.append(s)

    @retry(times=4, delays=[0.1], sleep=sleep_fn, exceptions=(ValueError,))
    def flaky():
        raise ValueError("error")

    with pytest.raises(ValueError):
        flaky()

    assert waits == [0.1, 0.1, 0.1]


def test_delays_none():
    waits = []

    def sleep_fn(s):
        waits.append(s)

    @retry(times=3, delays=None, sleep=sleep_fn, exceptions=(ValueError,))
    def flaky():
        raise ValueError("error")

    with pytest.raises(ValueError):
        flaky()

    assert waits == [1, 1]


def test_no_sleep_after_final_attempt():
    waits = []

    def sleep_fn(s):
        waits.append(s)

    @retry(times=3, sleep=sleep_fn, exceptions=(ValueError,))
    def flaky():
        raise ValueError("error")

    with pytest.raises(ValueError):
        flaky()

    assert len(waits) == 2  # Should sleep before 2nd and 3rd attempt, but not after 3rd.


def test_preserves_metadata():
    @retry(times=3)
    def my_function():
        """My docstring."""
        pass

    assert my_function.__name__ == "my_function"
    assert my_function.__doc__ == "My docstring."
